import { useState } from 'react';
import { AppHeader } from '../../slots/defs/appHeader';
import { useAsOf, useCurrentSheet, useCurrentUser } from '../../session/session';
import { useSheet } from './sheet';

// The screen's as-of date: while one is set, every cell shows the sheet as it stood at the end of that
// date (the date standing in for the sheet's today), and every change is refused. Only this screen's.
function SheetAsOf() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [, setAsOf] = useAsOf();
  const loaded = useSheet(sheet);
  const [input, setInput] = useState('');

  if (!user || sheet === '') return null;
  return (
    <form
      data-testid="asof-form"
      onSubmit={(e) => {
        e.preventDefault();
        const date = input.trim();
        if (/^\d{4}-\d{2}-\d{2}$/.test(date)) setAsOf(date);
      }}
    >
      As of <strong data-testid="sheet-asof">{loaded.data?.asOf ?? ''}</strong>{' '}
      <input data-testid="asof-date" type="date" value={input} onChange={(e) => setInput(e.target.value)} />
      <button type="submit" data-testid="asof-set">
        Show as of
      </button>
      <button type="button" data-testid="asof-clear" onClick={() => setAsOf(undefined)}>
        Show as now
      </button>
    </form>
  );
}

export const contribution = AppHeader.fill({ order: 25, Component: SheetAsOf });
    private final JdbcTemplate jdbc;

    public SheetStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's today: as set on the sheet, else the real date. */
    public LocalDate today(String sheetId) {
        List<LocalDate> found = jdbc.query("SELECT today FROM sheet WHERE id = ?",
                (rs, i) -> rs.getObject(1, LocalDate.class), sheetId);
        return found.isEmpty() ? LocalDate.now() : found.get(0);
    }

    public void setToday(String sheetId, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", sheetId, today);
    }

    /** Records that the sheet has been loaded: from then on it exists. */
    public void markLoaded(String sheetId) {
        jdbc.update("MERGE INTO sheet_loaded (id) KEY (id) VALUES (?)", sheetId);
    }
# POST /api/sheets/{sheetId}/people/{personId}/plans — add a plan to a person (body: {amount, start, every,
# end, user}): a DRAFT claim of the amount for every plan date (the start, then every N days) up to the end,
# made by POST plans/generate. The amount is a number with up to two decimals, every a whole number of at
# least 1, the dates yyyy-MM-dd (a blank start the sheet's today). Refused (400), storing nothing, when any
# is not, the end is before the start, or the person is not on the sheet. Recorded as PLAN_ADDED.
validate:
  class: net.officefloor.hq.app.plan.ValidatePlan
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.plan.SavePlan
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.plan.AuditPlanAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.plan.RespondWithPlan
  govern: [ transaction ]

